def park_by_key(key: str) -> Park | None:
    return next((p for p in PARKS if p.key == key), None)


# --- the map ---------------------------------------------------------------

_MAP_INSETS = {
    "conus": {
        "lon_min": -125.0, "lon_max": -66.9,
        "lat_min": 24.4, "lat_max": 49.5,
        "w": 660, "h": 400,
    },
    "alaska": {
        "lon_min": -172.0, "lon_max": -129.0,
        "lat_min": 51.0, "lat_max": 71.5,
        "w": 150, "h": 110,
    },
    "hawaii": {
        "lon_min": -160.3, "lon_max": -154.7,
        "lat_min": 18.8, "lat_max": 22.3,
        "w": 110, "h": 70,
    },
}


def map_insets() -> dict:
    """The three inset boxes' lon/lat bounds and viewBox dimensions -- what
    `project()` and the state-border renderer need to place things
    correctly, without exposing the module's private dict directly."""
    return _MAP_INSETS


def project(lat: float, lon: float) -> tuple[str, float, float] | None:
    """Which inset a park's real coordinates fall in, and its pixel x/y
    within that inset's own SVG viewBox. None for the two territories
    outside all three insets (American Samoa, the Virgin Islands) -- they
    still show in the list, just not pinned on the map."""
    for name, box in _MAP_INSETS.items():
        if box["lon_min"] <= lon <= box["lon_max"] and box["lat_min"] <= lat <= box["lat_max"]:
            x = (lon - box["lon_min"]) / (box["lon_max"] - box["lon_min"]) * box["w"]
            y = (box["lat_max"] - lat) / (box["lat_max"] - box["lat_min"]) * box["h"]
            return name, x, y
    return None


